/*
 * Pro tips
 * - Use half-open ranges [start, end); end - start <= 1 is the base case.
 * - The last element is the pivot. Partition values smaller than it to the left and values >= it to the right.
 * - After swapping misplaced values, the next scans move past them; do not skip the scans or the pointers may stall.
 * - Place the pivot at the meeting point, then exclude it from BOTH recursive ranges.
 * - This mutates the input list and is not stable: equal elements need not retain their original order.
 * - Check empty, singleton, sorted, reverse-sorted, and all-equal lists.
 * - Average time is O(n log n), but this last-element pivot gives O(n squared) time on sorted, reverse-sorted, or all-equal input.
 * - Recursion uses O(log n) average stack space and O(n) worst-case space; large unbalanced inputs can overflow the stack.
 */

import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static void sortListInterval(List<Integer> unsortedList, int start, int end) {
        // If segment is 1 or 0, it's sorted
        if (end - start <= 1)
            return;

        // Using last element as the pivot
        int pivot = unsortedList.get(end - 1);
        int startPtr = start, endPtr = end - 1;

        // Partitioning process
        while (startPtr < endPtr) {
            // Find the next element from the left that is larger than or equal to the pivot
            while (unsortedList.get(startPtr) < pivot && startPtr < endPtr) {
                startPtr++;
            }

            // Find the next element from the right that is smaller than the pivot
            while (unsortedList.get(endPtr) >= pivot && startPtr < endPtr) {
                endPtr--;
            }

            // Swap if pointers haven't met
            if (startPtr != endPtr) {
                int temp = unsortedList.get(startPtr);
                unsortedList.set(startPtr, unsortedList.get(endPtr));
                unsortedList.set(endPtr, temp);
            }
        }

        // Place pivot in its final position
        int temp = unsortedList.get(startPtr);
        unsortedList.set(startPtr, unsortedList.get(end - 1));
        unsortedList.set(end - 1, temp);

        // Sort left and right of the pivot
        sortListInterval(unsortedList, start, startPtr);
        sortListInterval(unsortedList, startPtr + 1, end);
    }

    public static List<Integer> sortList(List<Integer> unsortedList) {
        sortListInterval(unsortedList, 0, unsortedList.size());
        return unsortedList;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> unsortedList = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        List<Integer> res = sortList(unsortedList);
        System.out.println(res.stream().map(String::valueOf).collect(Collectors.joining(" ")));
    }
}
